/*
 * Application restyle — helpers shared by every flow's data.js (generated by the `rebranding` skill).
 *
 * Only presentation helpers and the columns of pages that appear in several flows (e.g. Documents). Flow data stays in
 * each flow's data.js.
 */

import { html } from 'https://cdn.jsdelivr.net/npm/lit@3/+esm';

/** Document identifier first (semibold), then the secondary references as meta lines. */
export function documentCell(name, ...meta) {
  return html`
    <span class="rs-cell-stack">
      <span class="rs-subheading rs-truncate" title=${name}>${name}</span>
      ${meta.map(line => html`<span class="rs-meta rs-truncate" title=${line}>${line}</span>`)}
    </span>
  `;
}

