/** Row matcher for a document by the start of its name. */
export const isDocument = prefix => row => row.document.startsWith(prefix);

/** The document selected on the Documents page in the flows that don't pick another one. */
export const isSelectedDocument = isDocument('Documenz297');

const FILE_ICON = {
  pdf: { name: 'file-earmark-pdf', title: 'Native file: PDF' },
  text: { name: 'file-earmark-text', title: 'Native file: text' }
};

/** Quick info: checked-out lock, current-revision flag (lit when current) and the icon of the native file, if any. */
const documentInfo = ({ row }) => {
  const record = row.original;
  const current = (record.revisionStatus ?? record.status) === 'Current';
  const file = FILE_ICON[record.format ?? 'pdf'];
  return html`
    <span class="rs-inline">
      ${record.checkedOut ? html`<sl-icon name="lock" title="Checked out"></sl-icon>` : ''}
      <sl-icon
        class=${current ? 'rs-mark--success' : 'rs-mark'}
        name="flag"
        title=${current ? 'Current revision' : 'Not the current revision'}
      ></sl-icon>
      ${file ? html`<sl-icon name=${file.name} title=${file.title}></sl-icon>` : ''}
    </span>
  `;
};

/**
 * The actions menu of a document row: the legacy right-click menu, reachable from the row's ⋮ button. It is the same on
 * the main table and on the revisions table, and it follows the record: Check out / Check in and Add to / Remove from
 * clipboard depending on the document's current state.
 */
const documentMenu = ({ row }) => html`
  <sl-menu>
    <sl-menu-item value="operations"><sl-icon slot="prefix" name="gear"></sl-icon>Operations</sl-menu-item>
    <sl-menu-item value="edit"><sl-icon slot="prefix" name="pencil"></sl-icon>Edit</sl-menu-item>
    <sl-divider></sl-divider>
    <sl-menu-item value="download"><sl-icon slot="prefix" name="download"></sl-icon>Download</sl-menu-item>
    <sl-menu-item value="location"><sl-icon slot="prefix" name="geo-alt"></sl-icon>View location</sl-menu-item>
    ${row.original.checkedOut
      ? html`<sl-menu-item value="check-in"
          ><sl-icon slot="prefix" name="check2-circle"></sl-icon>Check in</sl-menu-item
        >`
      : html`<sl-menu-item value="check-out"><sl-icon slot="prefix" name="lock"></sl-icon>Check out</sl-menu-item>`}
    ${row.original.clipboard
      ? html`<sl-menu-item value="clipboard-remove"
          ><sl-icon slot="prefix" name="clipboard-x"></sl-icon>Remove from clipboard</sl-menu-item
        >`
      : html`<sl-menu-item value="clipboard"
          ><sl-icon slot="prefix" name="clipboard"></sl-icon>Add to clipboard</sl-menu-item
        >`}
    <sl-divider></sl-divider>
    <sl-menu-item value="revisions"><sl-icon slot="prefix" name="clock-history"></sl-icon>View revisions</sl-menu-item>
    <sl-menu-item value="transmittals"
      ><sl-icon slot="prefix" name="clipboard-check"></sl-icon>View Transmittals and DPs</sl-menu-item
    >
    <sl-menu-item value="history"><sl-icon slot="prefix" name="briefcase"></sl-icon>View business history</sl-menu-item>
  </sl-menu>
`;

