/** Operations of an external job document (SUD 3.0: 8 actions, Sign as Received instead of Emergency Approval). */
const externalOperations = [
  'Apply Progress',
  'Cancel Revision',
  'Change Revision Code',
  'Delete Duplicated Version',
  'Re-Apply Progress template',
  'Recalculate Progress',
  'Reset Progress',
  'Sign as Received'
].map(name => ({ name }));

/** Operations of a transmittal, by state (SUD 3.0): Working → Ready → Issued; an Issued transmittal has none left. */
const transmittalOperations = {
  Working: ['Generate Sheets', 'Mark Transmittal as Ready', 'Send comment package with consolidated comments'].map(
    name => ({ name })
  ),
  Ready: ['Continue Working on Transmittal', 'Generate Sheets', 'Issue Transmittal'].map(name => ({ name })),
  Issued: []
};

/** The Operations list is not fixed: it depends on the entity (document, transmittal) and on its state. */
export function operationsFor(record) {
  if (record.entity === 'transmittal') return transmittalOperations[record.state] ?? [];
  if (record.docClass?.startsWith('External')) return externalOperations;
  if (record.state === 'Approved') return operations;
  return internalOperations;
}

