/** Opens the action menu (⋮) of the n-th visible row of a table, as in the screenshots that show it open. */
export async function openRowMenu(selector, index) {
  const table = document.querySelector(selector);
  await table.updateComplete;
  const menus = table.shadowRoot.querySelectorAll('.table__action-menu');
  await customElements.whenDefined('sl-dropdown');
  menus[index]?.show();
}

/** Fills a table and, optionally, selects the first record matching `isSelected` and scrolls it into view. */
export async function mountTable(selector, { columns, data, isSelected, rowDisabled } = {}) {
  const table = document.querySelector(selector);
  await customElements.whenDefined('sl-table');
  table.columns = columns;
  table.data = data;
  if (rowDisabled) table.rowDisabled = rowDisabled;
  if (isSelected) {
    await table.updateComplete;
    table.setSelection(data.filter(isSelected).slice(0, 1));
    await table.updateComplete;
    table.shadowRoot.querySelector('[part~="row"][aria-selected="true"]')?.scrollIntoView({ block: 'center' });
  }
  return table;
}

/** Opens the dropdown of an `sl-header-item` (e.g. to show the navigation menu as it is in the screenshot). */
export async function openHeaderMenu(item) {
  await customElements.whenDefined('sl-header-item');
  await item.updateComplete;
  item.shadowRoot.querySelector('sl-dropdown')?.show();
}
